function toK(c){ return +c + 273.15; }
function convertTemp(v, from, to){
  v=+v; if(isNaN(v)) return {error:'请输入数值'};
  from=(from||'C').toUpperCase(); to=(to||'C').toUpperCase();
  if(['C','F','K'].indexOf(from)<0||['C','F','K'].indexOf(to)<0) return {error:'单位须为 C/F/K'};
  var k= from==='C'? toK(v) : from==='F'? (v-32)*5/9+273.15 : v;
  var out;
  if(to==='K') out=k;
  else if(to==='C') out=k-273.15;
  else out=(k-273.15)*9/5+32;
  out=Math.round(out*100)/100;
  return {value:out, from:from, to:to, note: v+' '+from+' = '+out+' '+to};
}
var EXPORTS={convertTemp:convertTemp};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TempConvertForgePure = EXPORTS; }
